Add the server with the `claude mcp add` command. See [Connect Claude Code to tools via MCP](https://code.claude.com/docs/en/mcp) for more details.
```bash
claude mcp add --transport http neo4j-mcp https://<instance-id>.mcp-instances.neo4j.io
```
This requires the Neo4j MCP server executable to be available on your system, installed using one of these options: [Homebrew](https://neo4j.com/docs/mcp/installation/#_install_with_homebrew) or [manual installation](https://neo4j.com/docs/mcp/installation/#_manual_server_installation).
```bash
claude mcp add neo4j-mcp \
--env NEO4J_MCP_URI=bolt://localhost:7687 \
--env NEO4J_MCP_USERNAME=neo4j \
--env NEO4J_MCP_PASSWORD=password \
--env NEO4J_MCP_DATABASE=neo4j \
--env NEO4J_MCP_READ_ONLY=true \
-- neo4j-mcp
```

Create / edit *mcp.json*:
```json
{
"servers": {
"neo4j-mcp": {
"type": "http",
"url": "https://<instance-id>.mcp-instances.neo4j.io"
}
}
}
```

{
"servers": {
"neo4j-mcp": {
"type": "stdio",
"command": "neo4j-mcp",
"env": {
"NEO4J_MCP_URI": "bolt://localhost:7687",
"NEO4J_MCP_USERNAME": "neo4j",
"NEO4J_MCP_PASSWORD": "password",
"NEO4J_MCP_DATABASE": "neo4j",
"NEO4J_MCP_READ_ONLY": "true",
"NEO4J_MCP_TELEMETRY": "false",
"NEO4J_MCP_LOG_LEVEL": "info",
"NEO4J_MCP_LOG_FORMAT": "text",
"NEO4J_MCP_SCHEMA_SAMPLE_SIZE": "100"
}
}
}
}

## Cursor configuration
Create / edit `.cursor/mcp.json` in your project (or `~/.cursor/mcp.json` for a global configuration). See [Model Context Protocol](https://cursor.com/docs/mcp) in the Cursor documentation for more details.
```json
{
"mcpServers": {
"neo4j-mcp": {
"url": "https://<instance-id>.mcp-instances.neo4j.io"
}
}
}
```

```json
{
"mcpServers": {
"neo4j-mcp": {
"command": "neo4j-mcp",
"env": {
"NEO4J_MCP_URI": "bolt://localhost:7687",
"NEO4J_MCP_USERNAME": "neo4j",
"NEO4J_MCP_PASSWORD": "password",
"NEO4J_MCP_DATABASE": "neo4j",
"NEO4J_MCP_READ_ONLY": "true",
"NEO4J_MCP_TELEMETRY": "false",
"NEO4J_MCP_LOG_LEVEL": "info",
"NEO4J_MCP_LOG_FORMAT": "text",
"NEO4J_MCP_SCHEMA_SAMPLE_SIZE": "100"
}
}
}
}
